window.REPLIKEN = [{"nr": 1, "speaker": "PF", "phase": "Einstieg", "a": 10.0, "b": 18.08, "lines": [{"a": 9.98, "b": 14.32, "text": "Guten Tag! Ich bin Takiyat, Pflegefachfrau in Ausbildung."}, {"a": 14.32, "b": 16.12, "text": "Sie sind Sami, richtig?"}, {"a": 16.12, "b": 18.23, "text": "Wie geht es Ihnen heute mit der Atmung?"}]}, {"nr": 2, "speaker": "P", "phase": "Einstieg", "a": 18.48, "b": 22.72, "lines": [{"a": 18.64, "b": 20.32, "text": "Besser als gestern."}, {"a": 20.32, "b": 22.87, "text": "Aber die Treppe wäre noch nichts für mich."}]}, {"nr": 3, "speaker": "PF", "phase": "Einstieg", "a": 23.12, "b": 30.8, "lines": [{"a": 23.14, "b": 24.72, "text": "Das glaube ich Ihnen."}, {"a": 24.72, "b": 26.84, "text": "Ich hätte ein paar Minuten Zeit."}, {"a": 26.84, "b": 30.95, "text": "Dürfte ich mit Ihnen über ein Thema sprechen, das mit Ihrer Lunge zu tun hat?"}]}, {"nr": 4, "speaker": "P", "phase": "Einstieg", "a": 31.2, "b": 35.2, "lines": [{"a": 32.12, "b": 34.14, "text": "Ich ahne schon, was kommt."}, {"a": 34.14, "b": 35.35, "text": "Aber bitte."}]}, {"nr": 5, "speaker": "PF", "phase": "Ask", "a": 36.0, "b": 41.2, "lines": [{"a": 36.02, "b": 39.28, "text": "Sie haben bei der Aufnahme angegeben, dass Sie rauchen."}, {"a": 39.28, "b": 41.35, "text": "Wie viel ist es im Moment am Tag?"}]}, {"nr": 6, "speaker": "P", "phase": "Ask", "a": 41.6, "b": 45.04, "lines": [{"a": 41.6, "b": 43.24, "text": "So zwanzig Stück."}, {"a": 43.24, "b": 45.19, "text": "Am Wochenende auch mal mehr."}]}, {"nr": 7, "speaker": "PF", "phase": "Ask", "a": 45.44, "b": 47.2, "lines": [{"a": 45.42, "b": 47.35, "text": "Und seit wann rauchen Sie?"}]}, {"nr": 8, "speaker": "P", "phase": "Ask", "a": 47.6, "b": 51.2, "lines": [{"a": 47.68, "b": 49.46, "text": "Seit ich sechzehn bin."}, {"a": 49.46, "b": 51.35, "text": "Also acht Jahre."}]}, {"nr": 9, "speaker": "PF", "phase": "Advise", "a": 52.0, "b": 68.08, "lines": [{"a": 52.06, "b": 54.08, "text": "Danke, dass Sie so offen sind."}, {"a": 54.08, "b": 56.72, "text": "Ich möchte Ihnen ehrlich sagen, was ich denke:"}, {"a": 56.72, "b": 61.0, "text": "Mit dem Rauchen aufzuhören ist das Wichtigste, was Sie für Ihre Lunge tun können."}, {"a": 61.0, "b": 65.42, "text": "Bei Asthma löst Rauch Anfälle aus und schwächt die Wirkung Ihrer Medikamente."}, {"a": 65.42, "b": 68.23, "text": "Ohne Rauch werden Anfälle wie dieser seltener."}]}, {"nr": 10, "speaker": "P", "phase": "Advise", "a": 68.48, "b": 70.96, "lines": [{"a": 68.48, "b": 71.11, "text": "Das sagt mein Hausarzt auch jedes Mal."}]}, {"nr": 11, "speaker": "PF", "phase": "Advise", "a": 71.36, "b": 73.84, "lines": [{"a": 71.38, "b": 73.99, "text": "Und trotzdem ist es schwer, oder?"}]}, {"nr": 12, "speaker": "P", "phase": "Advise", "a": 74.24, "b": 79.76, "lines": [{"a": 74.24, "b": 76.8, "text": "Ja. Ich hab's zweimal versucht."}, {"a": 76.8, "b": 79.91, "text": "Einmal drei Wochen, dann kam die Prüfungsphase."}]}, {"nr": 13, "speaker": "PF", "phase": "Assess", "a": 80.56, "b": 90.16, "lines": [{"a": 80.56, "b": 83.12, "text": "Drei Wochen sind eine echte Leistung."}, {"a": 83.12, "b": 85.38, "text": "Da wissen Sie schon, dass Sie es können."}, {"a": 85.38, "b": 87.82, "text": "Darf ich Ihnen zwei kurze Fragen stellen?"}, {"a": 87.82, "b": 90.31, "text": "Wann rauchen Sie morgens die erste Zigarette?"}]}, {"nr": 14, "speaker": "P", "phase": "Assess", "a": 90.56, "b": 93.84, "lines": [{"a": 90.58, "b": 92.52, "text": "Gleich nach dem Aufstehen."}, {"a": 92.52, "b": 93.99, "text": "Noch vor dem Kaffee."}]}, {"nr": 15, "speaker": "PF", "phase": "Assess", "a": 94.24, "b": 98.72, "lines": [{"a": 94.24, "b": 98.87, "text": "Und fällt es Ihnen schwer, an Orten nicht zu rauchen, wo es verboten ist?"}]}, {"nr": 16, "speaker": "P", "phase": "Assess", "a": 99.12, "b": 101.92, "lines": [{"a": 99.12, "b": 102.07, "text": "Hier im Krankenhaus merke ich es schon sehr."}]}, {"nr": 17, "speaker": "PF", "phase": "Assess", "a": 102.32, "b": 115.44, "lines": [{"a": 102.36, "b": 105.82, "text": "Das spricht für eine deutliche körperliche Abhängigkeit."}, {"a": 105.82, "b": 111.0, "text": "Das ist keine Willensschwäche, sondern eine Abhängigkeit, die man gut behandeln kann."}, {"a": 111.0, "b": 113.1, "text": "Auf einer Skala von null bis zehn:"}, {"a": 113.1, "b": 115.59, "text": "Wie wichtig ist Ihnen das Aufhören gerade?"}]}, {"nr": 18, "speaker": "P", "phase": "Assess", "a": 115.84, "b": 121.2, "lines": [{"a": 115.94, "b": 117.32, "text": "Nach dieser Woche?"}, {"a": 117.32, "b": 121.35, "text": "Eine Acht. Ich hatte richtig Angst, keine Luft zu kriegen."}]}, {"nr": 19, "speaker": "PF", "phase": "Assess", "a": 121.6, "b": 124.32, "lines": [{"a": 121.6, "b": 124.47, "text": "Eine Acht. Und warum keine Fünf?"}]}, {"nr": 20, "speaker": "P", "phase": "Assess", "a": 124.72, "b": 129.44, "lines": [{"a": 124.72, "b": 129.59, "text": "Weil ich wieder Fußball spielen will, ohne nach zehn Minuten keine Luft zu kriegen."}]}, {"nr": 21, "speaker": "PF", "phase": "Assist", "a": 130.24, "b": 146.32, "lines": [{"a": 130.3, "b": 132.34, "text": "Das ist ein starker Grund."}, {"a": 132.34, "b": 134.64, "text": "Dann schauen wir, was Ihnen helfen kann."}, {"a": 134.64, "b": 139.14, "text": "Wenn Sie möchten, spreche ich mit der Ärztin über eine Nikotinersatztherapie."}, {"a": 139.14, "b": 144.42, "text": "Das heißt zum Beispiel ein Pflaster für den Grundbedarf und Kaugummis für starke Momente."}, {"a": 144.42, "b": 146.47, "text": "Das lindert die Entzugserscheinungen."}]}, {"nr": 22, "speaker": "P", "phase": "Assist", "a": 146.72, "b": 148.8, "lines": [{"a": 146.8, "b": 148.95, "text": "Ist das nicht auch Nikotin?"}]}, {"nr": 23, "speaker": "PF", "phase": "Assist", "a": 149.2, "b": 158.88, "lines": [{"a": 149.2, "b": 152.5, "text": "Ja, aber ohne die Schadstoffe aus dem Rauch."}, {"a": 152.5, "b": 154.8, "text": "Und Sie reduzieren es nach und nach."}, {"a": 154.8, "b": 159.03, "text": "Mit Beratung zusammen sind die Erfolgschancen deutlich höher als allein."}]}, {"nr": 24, "speaker": "P", "phase": "Assist", "a": 159.28, "b": 161.28, "lines": [{"a": 159.28, "b": 161.43, "text": "Und wenn der Stress wieder kommt?"}]}, {"nr": 25, "speaker": "PF", "phase": "Assist", "a": 161.68, "b": 166.96, "lines": [{"a": 161.64, "b": 163.86, "text": "Genau daran arbeiten wir."}, {"a": 163.86, "b": 167.11, "text": "Was hat Ihnen beim letzten Mal in den drei Wochen geholfen?"}]}, {"nr": 26, "speaker": "P", "phase": "Assist", "a": 167.36, "b": 170.4, "lines": [{"a": 167.38, "b": 170.55, "text": "Sport. Und Kaugummi kauen."}]}, {"nr": 27, "speaker": "PF", "phase": "Assist", "a": 170.8, "b": 189.2, "lines": [{"a": 170.76, "b": 172.84, "text": "Gut, das nehmen wir mit."}, {"a": 172.84, "b": 176.68, "text": "Dazu gibt es eine kostenlose Telefonberatung zum Rauchstopp."}, {"a": 176.68, "b": 180.52, "text": "Dort ruft man Sie auf Wunsch auch zurück und begleitet Sie über Wochen."}, {"a": 180.52, "b": 186.88, "text": "Und es gibt ein kostenloses Online-Ausstiegsprogramm auf rauchfrei-info.de."}, {"a": 186.88, "b": 189.35, "text": "Ich gebe Ihnen ein Infoblatt mit allen Nummern."}]}, {"nr": 28, "speaker": "P", "phase": "Assist", "a": 189.6, "b": 191.2, "lines": [{"a": 189.62, "b": 191.35, "text": "Das klingt machbar."}]}, {"nr": 29, "speaker": "PF", "phase": "Assist", "a": 191.6, "b": 193.6, "lines": [{"a": 191.58, "b": 193.75, "text": "Möchten Sie sich ein Datum setzen?"}]}, {"nr": 30, "speaker": "P", "phase": "Assist", "a": 194.0, "b": 197.6, "lines": [{"a": 194.0, "b": 196.32, "text": "Ich rauche ja gerade sowieso nicht."}, {"a": 196.32, "b": 197.75, "text": "Dann ab heute."}]}, {"nr": 31, "speaker": "PF", "phase": "Arrange", "a": 198.4, "b": 209.44, "lines": [{"a": 198.54, "b": 201.04, "text": "Sehr gut. Dann halten wir fest:"}, {"a": 201.04, "b": 203.9, "text": "Ich spreche heute mit der Ärztin über das Pflaster."}, {"a": 203.9, "b": 205.58, "text": "Sie bekommen das Infoblatt."}, {"a": 205.58, "b": 208.28, "text": "Und morgen früh frage ich nach, wie die Nacht war."}, {"a": 208.28, "b": 209.59, "text": "Passt das für Sie?"}]}, {"nr": 32, "speaker": "P", "phase": "Arrange", "a": 209.84, "b": 213.28, "lines": [{"a": 209.86, "b": 213.43, "text": "Ja. Danke, dass Sie mich nicht belehrt haben."}]}, {"nr": 33, "speaker": "PF", "phase": "Arrange", "a": 213.68, "b": 218.64, "lines": [{"a": 213.82, "b": 216.1, "text": "Sie haben die Entscheidung selbst getroffen."}, {"a": 216.1, "b": 217.52, "text": "Ich begleite Sie nur."}, {"a": 217.52, "b": 218.79, "text": "Bis morgen, Sami."}]}];
